<?php $cart=$_SESSION['cart']??[];$subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$cart));$hasProduct=isset($cart['product']);$hasTraining=isset($cart['training']);$flash=$_SESSION['flash']??null;unset($_SESSION['flash']); ?>
<section class="checkout-head"><p class="site-kicker"><?= $hasTraining&&!$hasProduct?'VOTRE INSCRIPTION':'VOTRE COMMANDE' ?></p><h1><?= $hasTraining&&!$hasProduct?'Formation sélectionnée':'Votre panier' ?> <span><?= count($cart) ?> élément<?= count($cart)>1?'s':'' ?></span></h1></section><?php if($flash): ?><div class="site-flash"><?= htmlspecialchars($flash) ?></div><?php endif ?><?php if(!$cart): ?><section class="cart-empty"><strong>Votre sélection est vide</strong><p>Explorez séparément les formations ou les équipements professionnels.</p><div><a class="site-btn green" href="/formations">Catalogue des formations</a><a class="site-btn outline" href="/boutique">Boutique d’équipements</a></div></section><?php else: ?><section class="checkout-layout"><div class="checkout-main"><?php if($hasTraining): ?><div class="access-note distinction-note"><span>✓</span><p><strong>Inscription à une formation — aucune livraison</strong><br>Après paiement et activation du compte, l’accès apparaît dans votre académie en ligne.</p></div><?php endif ?><?php if($hasProduct): ?><div class="access-note shop-note"><span>▣</span><p><strong>Achat en boutique</strong><br>Les équipements physiques peuvent être retirés ou livrés.</p></div><?php endif ?><div class="checkout-box"><div class="box-heading"><h2>Votre sélection</h2><form method="post" action="/panier/vider"><button class="text-danger">Tout retirer</button></form></div><?php foreach($cart as $key=>$item): ?><article class="cart-item"><div class="cart-thumb <?= $key==='training'?'navy':'coral' ?>">IF</div><div><span><?= $key==='training'?'INSCRIPTION FORMATION':'ARTICLE BOUTIQUE' ?></span><h3><?= htmlspecialchars($item['name']) ?></h3><small><?= $key==='training'?'Accès pédagogique nominatif':'Quantité : '.$item['quantity'] ?></small><form method="post" action="/panier/supprimer"><input type="hidden" name="key" value="<?= htmlspecialchars($key) ?>"><button>Supprimer</button></form></div><strong><?= number_format($item['price']*$item['quantity'],0,',',' ') ?> FCFA</strong></article><?php endforeach ?></div></div><aside class="summary-card"><h2>Récapitulatif</h2><p><span>Montant</span><b><?= number_format($subtotal,0,',',' ') ?> FCFA</b></p><p><span><?= $hasProduct?'Livraison équipements':'Accès formation' ?></span><b class="free"><?= $hasProduct?'Choisie à l’étape suivante':'100 % numérique' ?></b></p><hr><p class="total"><span>Total</span><strong><?= number_format($subtotal,0,',',' ') ?> FCFA</strong></p><a class="site-btn gold wide" href="/commande"><?= $hasTraining&&!$hasProduct?'Finaliser mon inscription':'Continuer vers le paiement' ?> →</a><small class="safe">🔒 Transaction sécurisée</small></aside></section><?php endif ?>
